		array( '근관 재치료', 'preserve', '재근관치료와 동일 · 실패 신경치료 재시도', '<p>이전 근관치료 실패 시 <strong>기존 충전재 제거 후</strong> 재세척·재충전.</p>' ),
		array( '재신경치료', 'preserve', '근관 재치료와 동일', '<p>실패한 신경치료를 다시 시도. 성공률 80%+, 정밀 진단 필요.</p>' ),
		array( '의도적 재식술', 'preserve', '치아를 뽑았다가 재식립하는 최후의 신경치료', '<p>Intentional Replantation. 재근관치료 불가 시 <strong>발치 → 근관 처리 → 재식</strong>. 최후의 수단.</p>' ),
		array( '치아 균열 증후군', 'preserve', '치아에 미세 균열이 있어 씹을 때 통증', '<p>Cracked Tooth Syndrome. <strong>씹을 때만 순간적 예리한 통증</strong>. 조기 발견이 발치 예방.</p>' ),
		array( '치아 파절 (외상)', 'preserve', '외상으로 치아가 부러진 상태', '<p>파절 부위·깊이별 처치: <strong>레진·크라운·신경치료·발치</strong>. 24시간 내 응급 처치.</p>' ),
		array( '치아 변색 (외상성)', 'preserve', '외상으로 치아 색이 어두워짐', '<p>Traumatic Discoloration. 외상 후 <strong>치수 손상으로 어둡게 변색</strong>. 신경치료·워킹 블리치.</p>' ),
		array( '내부 미백 (워킹 블리치)', 'preserve', '신경치료된 치아 내부를 미백', '<p>Walking Bleach. 신경치료 후 어두워진 치아 <strong>내부에 미백제</strong>. 1~2주 후 확인.</p>' ),
		array( '치아 변색', 'preserve', '치아 색이 어두워지는 원인·치료', '<p>내인성(신경치료·약물)·외인성(음식·흡연). 미백·라미네이트·크라운으로 개선.</p>' ),
		array( '이차 우식', 'preserve', '기존 충전물 주변에 재발한 충치', '<p>Secondary Caries. 기존 보철·충전물 <strong>변연 미세 틈</strong>에서 세균 침투로 재발.</p>' ),
		array( '노인 뿌리 우식', 'preserve', '잇몸 퇴축으로 노출된 치근에 발생', '<p>Root Caries. 시니어에 흔함. <strong>불소도포·시린이 관리·정기 검진</strong>이 예방.</p>' ),
		array( '수산화칼슘', 'preserve', '신경치료·치수복조에 사용하는 재료', '<p>Ca(OH)₂. <strong>항균·재광화</strong>. 임시 근관 충전·직접치수복조 등에 사용.</p>' ),
		array( '광중합기', 'preserve', '레진 경화용 파란색 광 장치', '<p>Curing Light. 파란 LED 광으로 <strong>레진 광경화</strong>. 20초 이내 경화 완료.</p>' ),
		array( '본딩제', 'preserve', '레진을 치아에 접착시키는 접착제', '<p>Bonding Agent. 레진 충전 전 치아 표면에 도포해 <strong>강한 결합력</strong>. Etch-and-rinse·Self-etch.</p>' ),
		array( '복합레진', 'preserve', '심미레진과 동일 · 광경화 레진', '<p>Composite Resin. 광경화 <strong>복합 수지</strong>. 충치·심미치료에 널리 사용.</p>' ),
		array( '컴포짓 레진', 'preserve', '복합레진과 동일', '<p>Composite Resin. 폴리머 매트릭스에 실리카·글래스 필러 첨가. 강도·심미성 우수.</p>' ),
		array( '레진', 'preserve', '치과용 광중합 수지 통칭', '<p>치과 <strong>충전·심미·본딩</strong>에 광범위 사용. 광경화·자가경화·이중경화.</p>' ),
		array( '레진 인레이', 'preserve', '레진 소재의 간접 수복 인레이', '<p>Resin Inlay. 세라믹보다 <strong>저렴·심미성 양호</strong>. 큰 충치에 적합.</p>' ),
		array( '글래스 아이오노머', 'preserve', '불소 방출 시멘트/충전재 (GIC)', '<p>Glass Ionomer Cement. <strong>불소 방출·화학적 결합</strong>. 유치·치경부 충치·임시 충전에 사용.</p>' ),
		array( 'MTA (미네랄 트리옥사이드)', 'preserve', '신경치료·치수보존 첨단 재료', '<p>Mineral Trioxide Aggregate. 생체친화적, <strong>봉쇄력 우수</strong>. 치근천공·역행성 근관치료·치수복조.</p>' ),
		array( '구타페르카', 'preserve', '거타퍼차와 동일 · 신경관 최종 충전재', '<p>Gutta-percha. 신경관 밀봉 재료. 씰러와 함께 사용.</p>' ),
		array( '치수', 'preserve', '치아 내부 신경·혈관 조직', '<p>Pulp. 치아 신경·혈관. 치수염 → 신경치료 대상.</p>' ),
