		array( '치수염', 'preserve', '치수의 염증 · 가역·비가역', '<p>Pulpitis. 가역성(회복 가능)·비가역성(신경치료 필요) 구분.</p>' ),
		array( '치근단', 'preserve', '치아 뿌리 끝 부위', '<p>Apex. 치근의 끝. <strong>신경·혈관이 드나드는 유공</strong>.</p>' ),
		array( '바이탈리티 테스트', 'preserve', '치수 생존 여부 검사', '<p>Vitality Test. <strong>냉·열·전기 자극</strong>으로 치수 반응 확인. 신경치료 필요성 판단.</p>' ),
		array( '타악', 'preserve', '치아 두드림으로 통증 확인', '<p>Percussion. 기구로 <strong>치아를 두드려</strong> 치근 주위 염증 여부 확인.</p>' ),

