		array( '치주 유지관리', 'periodontics', 'SPT · 재발 방지 정기 관리', '<p>Supportive Periodontal Therapy. 치주치료 후 <strong>3~6개월 간격 정기</strong> 관리.</p>' ),
		array( '치주 수술 후 관리', 'periodontics', '수술 후 회복·재발 방지', '<p>1주 강한 양치 자제·부드러운 음식·항생제·정기 세척. <strong>2주 후 실밥 제거</strong>.</p>' ),
		array( '치은 이식 종류', 'periodontics', '유리치은·결합조직 이식 등', '<p>FGG(유리치은 이식)·CTG(결합조직 이식)·터널 테크닉 등 <strong>목적별 선택</strong>.</p>' ),
		array( '치은 이식술', 'periodontics', '잇몸 이식과 동일', '<p>Gum Grafting. 잇몸 퇴축·부착치은 부족에 이식.</p>' ),
		array( '치은 절제술', 'periodontics', '잇몸을 절제해 라인 조정', '<p>Gingivectomy. 잇몸 <strong>과증식·불규칙 라인 절제</strong>. 심미·기능 개선.</p>' ),
		array( '잇몸 절제술', 'periodontics', '치은 절제술과 동일', '<p>레이저 또는 메스로 잇몸을 절제. 회복 1~2주.</p>' ),
		array( '치은 비대', 'periodontics', '잇몸이 비정상적으로 커진 상태', '<p>Gingival Hyperplasia. <strong>약물성·유전성</strong>. 잇몸 절제술로 개선.</p>' ),
		array( '약물성 치은 증식', 'periodontics', '항간질약·면역억제제 등 약물 부작용', '<p>Drug-induced Gingival Overgrowth. <strong>페니토인·사이클로스포린·니페디핀</strong> 등 원인.</p>' ),
		array( '임신성 치은염', 'periodontics', '임신 중 호르몬 변화로 심해지는 치은염', '<p>Pregnancy Gingivitis. <strong>호르몬으로 잇몸 예민</strong>. 스케일링·구강위생으로 관리.</p>' ),
		array( '치은 출혈', 'periodontics', '잇몸 출혈과 동일', '<p>Gingival Bleeding. 치은염·치주염의 대표 증상. 조기 대응 필수.</p>' ),
		array( '치은열구', 'periodontics', '정상 잇몸과 치아 사이 좁은 홈', '<p>Gingival Sulcus. 정상 깊이 <strong>1~3mm</strong>. 4mm 넘으면 치주낭.</p>' ),
		array( '치은', 'periodontics', '잇몸의 의학 용어', '<p>Gingiva. 치아를 감싸고 있는 <strong>구강 점막</strong>.</p>' ),
		array( '치은염', 'periodontics', '잇몸에 국한된 초기 염증', '<p>Gingivitis. 치석·치태로 인한 <strong>잇몸 표면 염증</strong>. 회복 가능한 초기 단계.</p>' ),
		array( '치주 농양', 'periodontics', '치주 포켓 안 화농성 염증', '<p>Periodontal Abscess. 심한 잇몸 통증·부기·고름. 즉시 배농·항생제.</p>' ),
		array( '치주 스플린트', 'periodontics', '흔들리는 치아를 인접 치아와 연결', '<p>Splinting. 치주염으로 <strong>흔들리는 치아를 인접 치아와 결합</strong>해 안정화.</p>' ),
		array( '부착치은', 'periodontics', '치아에 단단히 붙어있는 각화 잇몸', '<p>Attached Gingiva. 치아 뿌리와 <strong>단단히 결합된 잇몸</strong>. 부족 시 이식 필요.</p>' ),
		array( '잇몸 색소침착', 'periodontics', '멜라닌 등으로 잇몸이 검게 됨', '<p>Gingival Pigmentation. 인종·흡연·약물 원인. <strong>잇몸 미백(레이저)</strong>으로 개선.</p>' ),
		array( 'BOP (탐침 시 출혈)', 'periodontics', '치주 검사의 핵심 지표', '<p>Bleeding on Probing. 프로빙 시 <strong>출혈 여부</strong>. 활동성 치주염 지표.</p>' ),
		array( '프로빙', 'periodontics', '치주 포켓 깊이 측정', '<p>Probing. 치주 프로브로 <strong>치주낭 깊이 mm 측정</strong>. 치주 진단 기본.</p>' ),
		array( '플라크 지수', 'periodontics', '치태 축적 정도를 수치화', '<p>Plaque Index (PI). 치아 표면 <strong>치태 양을 0~3점</strong>으로 평가. 위생 상태 추적.</p>' ),

