		array( '디지털 스마일 디자인', 'aesthetic', 'DSD와 동일', '<p>디지털 시뮬레이션으로 심미 치료 결과 예측.</p>' ),
		array( '보툴리눔', 'aesthetic', '보톡스와 동일 · A형 독소', '<p>Botulinum Toxin A. 근육을 <strong>일시적으로 마비</strong>시켜 사각턱 축소·이갈이·거미스마일 개선.</p>' ),

