		array( '세라믹', 'prosthetics', '치과용 세라믹 통칭', '<p>Ceramic. <strong>지르코니아·리튬 디실리케이트(e.max)·글래스 세라믹</strong> 등.</p>' ),
		array( '하이브리드 세라믹', 'prosthetics', '레진과 세라믹 혼합 재료', '<p>Hybrid Ceramic. 세라믹 강도 + 레진 유연성. <strong>Cerasmart·Vita Enamic</strong> 대표.</p>' ),
