		array( '교합기', 'prosthetics', '위·아래 턱의 관계를 재현하는 장치', '<p>Articulator. 반조절성·완전조절성. <strong>보철 제작·교정 진단</strong>에 사용.</p>' ),
		array( '대합치', 'prosthetics', '반대편 턱에서 맞물리는 치아', '<p>Opposing Tooth. 위 어금니의 대합치는 <strong>같은 위치 아래 어금니</strong>. 대합치 없으면 정출 위험.</p>' ),
		array( '교합', 'prosthetics', '위·아래 치아가 맞물리는 관계', '<p>Occlusion. 정상 교합·부정교합. 보철·교정의 <strong>궁극 목표</strong>.</p>' ),
