		array( '의료폐기물', 'surgery', '치과에서 배출되는 감염성 폐기물', '<p>주사바늘·거즈·발치된 치아 등. <strong>전용 통·전문 업체 처리</strong>.</p>' ),
		array( '치과 응급 상황', 'surgery', '외상·심한 통증·부기 등', '<p>치아 완전 탈구·심한 부기·외상. <strong>즉시 응급실 또는 야간 치과</strong>.</p>' ),

