		array( '교합기 (TMJ)', 'tmj', '턱관절 진단·보철에 사용', '<p>턱관절 움직임을 <strong>기계적으로 재현</strong>하는 장치.</p>' ),

		/* ==================== 소아 (추가) ==================== */
		array( '유치 충치', 'pediatric', '어린이 유치에 발생한 충치', '<p>영구치보다 <strong>진행 빠름</strong>. 방치 시 신경치료·조기 상실.</p>' ),
		array( '어린이 충치 예방', 'pediatric', '실런트·불소·정기 검진', '<p>어린이 큰어금니 나오면 실런트, 3~6개월 불소도포, <strong>6개월 정기 검진</strong>.</p>' ),
		array( '치아 맹출 지연', 'pediatric', '평균보다 늦게 나는 치아', '<p>Eruption Delay. 유전·영양·과잉치·낭종 등 원인. <strong>X-ray로 확인</strong>.</p>' ),
		array( '유치 조기 상실', 'pediatric', '영구치 나오기 전 빠짐', '<p>영구치 <strong>공간 부족 위험</strong>. 공간유지장치 필요.</p>' ),
		array( '핫 앤 피셔 실란트', 'pediatric', '어금니 홈메우기 재료 종류', '<p>Hot·Fissure Sealant. 광경화 실런트·자가경화 실런트. <strong>어금니 홈 완전 밀봉</strong>.</p>' ),
		array( '지도설', 'pediatric', '혀 표면에 지도처럼 얼룩이 생기는 양성 상태', '<p>Geographic Tongue. 혀 표면 <strong>불규칙한 붉은 반점</strong>. 치료 불필요.</p>' ),
		array( '소아 진정치료', 'pediatric', '공포·움직임 심한 아이 진정 치료', '<p>Pediatric Sedation. <strong>아산화질소·경구 진정제</strong>. 전문 소아치과에서만.</p>' ),
		array( '소아 보호대', 'pediatric', '치료 중 아이 움직임 제한', '<p>Papoose Board. 필수적일 때만 <strong>부드러운 랩</strong>으로 안전한 치료 환경 확보.</p>' ),
		array( '행동조절', 'pediatric', 'Tell-Show-Do 등 소아 행동 유도', '<p>Behavior Management. <strong>Tell-Show-Do·긍정 강화</strong>로 아이가 편하게 진료받게.</p>' ),
		array( '어린이 실런트', 'pediatric', '유·영구 어금니 홈메우기', '<p>영구치 큰어금니가 나온 직후 <strong>홈메우기로 충치 예방률 90%+</strong>.</p>' ),
		array( '스케일링 협조', 'pediatric', '어린이 스케일링 협조 유도', '<p>연령·성격별 접근. <strong>Tell-Show-Do</strong>·짧은 시간·긍정 강화.</p>' ),

		/* ==================== 예방·검진 (추가) ==================== */
		array( '정기검진', 'prevention', '6개월 주기 구강 검진', '<p>Regular Check-up. <strong>6개월~1년 주기</strong>. 조기 발견이 최선의 예방.</p>' ),
		array( '정기 검진 주기', 'prevention', '일반 6개월·고위험군 3개월', '<p>일반인 <strong>6개월</strong>. 치주염·임플란트·당뇨·흡연자는 <strong>3~4개월</strong>.</p>' ),
		array( '구강검진', 'prevention', '정기 구강 종합 검사', '<p>Oral Examination. 시진·촉진·X-ray. <strong>충치·치주염·구강암 조기 발견</strong>.</p>' ),
		array( '우식 위험도 평가', 'prevention', '개인별 충치 위험 등급 산정', '<p>Caries Risk Assessment. 식습관·타액·불소 노출 등 평가. <strong>예방 계획 개별화</strong>.</p>' ),
		array( '타액검사', 'prevention', '침으로 충치 위험 세균 측정', '<p>Saliva Test. <strong>뮤탄스균·락토바실러스 수</strong>·타액 pH·완충 능력 측정.</p>' ),
		array( '치아에 좋은 음식', 'prevention', '치즈·녹차·견과·물', '<p>치즈·<strong>녹차(폴리페놀)</strong>·견과·물. 산성·당 음식 피하기.</p>' ),
		array( '치아에 나쁜 습관', 'prevention', '이갈이·손톱 물기·얼음 씹기', '<p>이갈이·손톱 물기·<strong>얼음·펜 씹기</strong>·강한 산성 음료. 파절·마모 원인.</p>' ),
		array( '올바른 칫솔질 방법', 'prevention', '3·3·3 원칙 + 회전법', '<p><strong>하루 3회·식후 3분·3분 이상</strong>. 잇몸에서 치아 방향으로 회전법(로테이션).</p>' ),
		array( '칫솔질', 'prevention', '충치·치주염 예방의 기본', '<p>Brushing. 하루 <strong>최소 2회 이상</strong>, 자기 전 필수. 부드러운 칫솔 권장.</p>' ),
		array( '치약 성분', 'prevention', '불소·연마제·계면활성제', '<p>주요 성분: <strong>불소(재광화)·연마제·계면활성제·항균제</strong>. 성인은 1000ppm 이상 불소.</p>' ),
		array( '불소', 'prevention', '충치 예방의 핵심 무기물', '<p>Fluoride. <strong>법랑질 강화·재광화·항균</strong>. 치약·물·도포로 공급.</p>' ),
		array( '불소 바니시', 'prevention', '고농도 불소 도포용 바니시', '<p>Fluoride Varnish. <strong>5% NaF</strong>. 도포 후 4시간 음식 금지.</p>' ),
		array( '자일리톨', 'prevention', '충치 예방 효과 있는 대체 감미료', '<p>Xylitol. 뮤탄스균이 <strong>대사하지 못하는 당</strong>. 껌·사탕으로 섭취.</p>' ),
		array( '프로바이오틱스', 'prevention', '유익균으로 구강 건강 개선', '<p>Oral Probiotics. Streptococcus salivarius 등. <strong>구취·치주염 개선</strong> 효과 연구 중.</p>' ),
		array( '혀 클리너', 'prevention', '설태 제거 전용 도구', '<p>Tongue Scraper. 혀 표면 <strong>흰 막(설태) 제거</strong>. 구취 완화.</p>' ),
		array( '구강 세정기', 'prevention', '워터픽 · 수압 청소기', '<p>Water Flosser. 수압으로 <strong>치간·잇몸 라인 청소</strong>. 임플란트·교정에 유용.</p>' ),
		array( '구강 세정제', 'prevention', '살균·불소 함유 가글', '<p>Mouthwash. 클로르헥시딘·불소·염화세틸피리디늄. <strong>양치 보조</strong>.</p>' ),
		array( '엑스레이 (X-ray)', 'prevention', '치아·잇몸뼈·신경 X선 촬영', '<p>파노라마·치근단·교익·CBCT. <strong>극소량 방사선</strong>으로 안전.</p>' ),
		array( '치과 CT (CBCT)', 'prevention', '3D 정밀 진단 CT', '<p>Cone Beam CT. <strong>3D 입체 진단</strong>. 임플란트·매복치·근관에 필수.</p>' ),
		array( '파노라마', 'prevention', '전체 치아·턱뼈 한 장 촬영', '<p>Panorama X-ray. 상하악 <strong>전체를 한 장</strong>에 촬영. 사랑니·전체 구조 확인.</p>' ),
		array( '파노라마 X선', 'prevention', '파노라마와 동일', '<p>파노라마 X-ray. 전체 치아·턱관절 개관.</p>' ),
		array( '파노라마 촬영', 'prevention', '전체 X-ray 촬영 과정', '<p>10초 이내 촬영. 서 있거나 앉아서 진행. <strong>얼굴을 고정</strong>하고 정지.</p>' ),
		array( '세팔로 X선', 'prevention', '옆얼굴 X-ray · 교정 진단', '<p>Cephalometric. 교정 진단 필수. <strong>골격·치아·연조직 각도</strong> 측정.</p>' ),
		array( '방사선 안전', 'prevention', '치과 X-ray의 극소량 안전성', '<p>디지털 X-ray는 <strong>필름 대비 1/4~1/10</strong> 방사선. 안전.</p>' ),
		array( '방사선 방어', 'prevention', '납 앞치마·갑상선 보호대', '<p>Lead Apron·Thyroid Collar. <strong>모든 촬영 시 착용</strong>. 임산부·소아 필수.</p>' ),
		array( '방사선량', 'prevention', '치과 X-ray의 극소량', '<p>파노라마 1회 = <strong>비행기 3~5시간</strong> 우주선. 극도로 안전.</p>' ),
		array( '치아 번호 체계', 'prevention', 'FDI·유니버설·파머 표기법', '<p>FDI(11~48 국제표준)·<strong>Universal(1~32 미국)</strong>·Palmer(사분면 표기).</p>' ),
		array( '치아 색상 (셰이드)', 'prevention', 'A1~D4 표준 등급', '<p>Vita Shade Guide. <strong>A1이 가장 밝고 D4가 가장 어두움</strong>.</p>' ),

		/* ==================== 일반·해부·마취·병원 운영 (추가) ==================== */
		array( '치아 번호', 'general', 'FDI 국제 표기법 (11~48)', '<p>FDI 시스템. 상악 우측(1사분면) → 상악 좌측(2) → 하악 좌측(3) → 하악 우측(4). <strong>사분면·번호 조합</strong>.</p>' ),
		array( '치식 (표기법)', 'general', '치아 위치 국제 표기법', '<p>Dental Notation. FDI 대표. <strong>11~48 두 자리 숫자</strong>로 32개 치아 표시.</p>' ),
		array( '치아 발육 단계', 'general', '개시기→종상기→관상기→뿌리 형성기', '<p>Tooth Development. <strong>배아 6주부터 시작</strong>. 유치 6개월~2.5세 맹출, 영구치 6세~.</p>' ),
		array( '치아 맹출', 'general', '치아가 잇몸을 뚫고 나오는 과정', '<p>Eruption. 유치 6개월~2.5세, 영구치 6~13세, 사랑니 17~25세.</p>' ),
		array( '맹출', 'general', '치아 맹출과 동일', '<p>치아가 나오는 과정. <strong>맹출 지연</strong> 시 X-ray 확인.</p>' ),
		array( '유치', 'general', '어린이의 젖니 · 총 20개', '<p>Primary Teeth. <strong>6개월~2.5세 맹출, 6~12세 영구치로 교체</strong>.</p>' ),
	    array( '영구치', 'general', '평생 사용하는 성인 치아 · 총 28~32개', '<p>Permanent Teeth. <strong>6세부터 유치와 교체</strong>. 사랑니 포함 최대 32개.</p>' ),
		array( '어금니', 'general', '큰어금니(대구치)와 작은어금니(소구치)', '<p>Molar & Premolar. 음식을 <strong>부수고 갈아내는</strong> 역할.</p>' ),
		array( '앞니', 'general', '중절치·측절치 총 8개', '<p>Incisor. 음식 <strong>자르는 역할</strong>. 얼굴 인상 결정.</p>' ),
		array( '견치', 'general', '송곳니와 동일', '<p>Canine. 뾰족한 <strong>4번째 치아</strong>. 안모 형성·저작 지지.</p>' ),
		array( '소구치', 'general', '작은어금니 총 8개', '<p>Premolar. 어금니 중 작은 것. <strong>발치 교정</strong> 시 자주 뽑힘.</p>' ),
		array( '치관', 'general', '잇몸 위 치아 부분', '<p>Crown. <strong>잇몸 밖으로 노출된 치아</strong>. 법랑질로 덮임.</p>' ),
		array( '치근', 'general', '잇몸 속 치아 뿌리', '<p>Root. 잇몸 속 뿌리. <strong>치조골에 고정</strong>.</p>' ),
		array( '치수', 'general', '치아 내부 신경·혈관', '<p>Pulp. 신경·혈관·결합조직. <strong>치수염 → 신경치료</strong>.</p>' ),
		array( '상아질', 'general', '법랑질 아래 노란 조직', '<p>Dentin. 치아의 대부분. <strong>노란색</strong>. 자극 전달 (시린 원인).</p>' ),
		array( '법랑질', 'general', '치아 표면의 가장 단단한 조직', '<p>Enamel. 인체에서 <strong>가장 단단</strong>. 96% 무기질. 재생 안 됨.</p>' ),
		array( '백악질', 'general', '치근 표면의 얇은 조직', '<p>Cementum. 시멘트질. <strong>치주인대와 치조골 연결</strong>.</p>' ),
		array( '치조골', 'general', '치아를 지탱하는 턱뼈 부분', '<p>Alveolar Bone. <strong>치아 뿌리를 감싸는 턱뼈</strong>. 발치 후 흡수.</p>' ),
		array( '교두', 'general', '어금니 씹는 면의 돌출부', '<p>Cusp. 어금니 씹는 면의 <strong>4~5개 뾰족한 돌출</strong>. 저작 담당.</p>' ),
		array( '협면', 'general', '치아의 볼 쪽 면', '<p>Buccal Surface. 어금니의 <strong>볼 쪽 면</strong>. 청소 소홀 부위.</p>' ),
		array( '설면', 'general', '치아의 혀 쪽 면', '<p>Lingual Surface. 하악 치아의 <strong>혀 쪽 면</strong>. 상악은 구개면(Palatal).</p>' ),
		array( '협측/설측', 'general', '치아 위치 표기 · 볼쪽/혀쪽', '<p>Buccal/Lingual. 치아 5면 중 <strong>볼쪽·혀쪽</strong> 방향.</p>' ),
		array( '치아 균열 증후군', 'general', '미세 균열로 인한 씹기 통증', '<p>Cracked Tooth Syndrome. <strong>씹을 때만 예리한 통증</strong>. 조기 진단 어려움.</p>' ),
		array( '치아 과민증', 'general', '차가운·뜨거운 자극에 시린 증상', '<p>Dentin Hypersensitivity. <strong>상아질 노출</strong> 원인. 시린이 치약·불소도포·레진.</p>' ),
		array( '치아 흔들림', 'general', '치주염·외상·과부하로 흔들리는 치아', '<p>Mobility. <strong>0~3도 분류</strong>. 원인별 스플린트·치주치료·발치.</p>' ),

		/* ==================== 마취·진정 ==================== */
		array( '마취', 'surgery', '치과 진료 시 통증 감소', '<p>Anesthesia. <strong>표면·침윤·전달 마취</strong>. 통증 없이 시술 가능.</p>' ),
		array( '국소마취', 'surgery', '해당 부위만 마취하는 표준 방식', '<p>Local Anesthesia. <strong>침윤 마취·전달 마취</strong>. 리도카인·아르티카인 대표.</p>' ),
		array( '침윤마취', 'surgery', '치아 주변에 직접 마취제 주입', '<p>Infiltration. 잇몸에 <strong>직접 주사</strong>. 상악 치아에 주로 사용.</p>' ),
		array( '전달마취', 'surgery', '신경 다발에 마취제로 광범위 마취', '<p>Nerve Block. 하악 어금니 부위 <strong>하치조 신경 전달</strong> 마취 대표.</p>' ),
		array( '아산화질소', 'surgery', '웃음가스 · 흡입 진정', '<p>Nitrous Oxide. <strong>소아·공포증 환자용</strong> 흡입 진정. 안전.</p>' ),
		array( '수면 진정', 'surgery', '경구·정맥 진정제로 편안한 상태', '<p>IV/Oral Sedation. 완전 수면 아닌 <strong>깊은 이완 상태</strong>. 사랑니·임플란트에 활용.</p>' ),
		array( '진정 치료', 'surgery', '수면 진정과 동일', '<p>Sedation. 불안·공포 환자용 <strong>이완 유도</strong>.</p>' ),

		/* ==================== 재료·장비 ==================== */
		array( '티타늄', 'general', '임플란트 표준 소재 · 생체친화적', '<p>Titanium. <strong>알레르기 거의 없음·가벼움·강함·골유착</strong>. 임플란트 표준.</p>' ),
		array( '핸드피스', 'general', '치과 회전 기구 통칭 · 드릴', '<p>Handpiece. 고속·저속. 충치 제거·치아 삭제·연마에 사용.</p>' ),
