		array( '호르몬과 치과', 'general', '여성 호르몬 변화의 구강 영향', '<p>사춘기·임신·폐경기 호르몬 변화가 <strong>잇몸·구강 건강</strong>에 영향.</p>' ),
		array( '폐경기 구강건조', 'general', '폐경 호르몬 변화로 침 감소', '<p>Menopausal Xerostomia. 에스트로겐 감소로 <strong>침 분비 감소</strong>. 관리 필요.</p>' ),
		array( '심혈관 환자 치과', 'general', '심장 질환 환자 진료 주의', '<p>Cardiac Patient Dental Care. <strong>사전 항생제·혈압 모니터링·응급 대비</strong>.</p>' ),
		array( '당뇨 환자 치과', 'general', '당뇨 환자 진료 주의사항', '<p>Diabetic Dental Care. <strong>혈당 확인·감염 위험 관리</strong>. 임플란트 가능.</p>' ),
